<template>
  <div class="category-view">
    <NavBarVue />
    <div class="card">
      <div class="card-body text-secondary">
        <b-row>
          <b-col lg="9">
            <b-row>
              <b-col lg="4">
                <h5 class="text-dark">
                  <b
                    ><b-icon icon="people-fill"></b-icon> Mutuários:
                    {{ customers.length }}
                  </b>
                </h5>
              </b-col>
              <b-col>
                <b-input-group size="sm" class="">
                  <b-input-group-prepend is-text>
                    <b-icon icon="search"></b-icon>
                  </b-input-group-prepend>
                  <b-form-input
                    type="text"
                    size="sm"
                    @keyup="searchCustomers()"
                    v-model="searchValues"
                    placeholder="Pesquisar clientes"
                  ></b-form-input>
                </b-input-group>
              </b-col>
              <b-col lg="2">
                <b-button
                  size="sm"
                  block
                  variant="secondary"
                  @click="downloadCustomerList()"
                >
                  <b-icon icon="file-earmark-pdf-fill"></b-icon>
                  <small> PDF</small></b-button
                >
              </b-col>
              <b-col lg="2">
                <b-button
                  size="sm"
                  block
                  variant="secondary"
                  @click="downloadCustomerListExcel()"
                >
                  <b-icon icon="file-earmark-excel-fill"></b-icon>
                  <small> Excel</small></b-button
                >
              </b-col>
              <b-col lg="1">
                <b-button
                  size="sm"
                  block
                  variant="secondary"
                  @click="refreshCustomers()"
                >
                  <b-icon icon="arrow-clockwise"></b-icon
                ></b-button>
              </b-col>
            </b-row>
            <b-row>
              <b-col>
                <b-overlay :show="isLoading" rounded="sm">
                  <p class="text-danger mt-1" v-if="customers.length == 0">
                    Sem nenhum mutuário cadastrado até o momento.
                  </p>
                  <table
                    v-else
                    class="table table-sm table-hover table-stripped mt-1"
                  >
                    <thead>
                      <tr
                        style="font-size: 10pt"
                        class="bg-secondary text-white"
                      >
                        <th>Nome completo</th>
                        <th>Telemóvel</th>
                        <th>E-mail</th>
                        <th>NUIT</th>
                        <th>Profissão</th>
                        <th>Endereço</th>
                        <th>Data de cadastro</th>
                        <th class="text-center">Configs</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr
                        v-for="customer in customers"
                        :key="customer.id"
                        style="font-size: 9pt; cursor: pointer"
                        :class="{
                          'text-danger': customer.status === 0,
                          'bg-warning': form.id === customer.id,
                        }"
                      >
                        <td>{{ customer.customerName }}</td>
                        <td>{{ customer.customerPhone }}</td>
                        <td>{{ customer.customerEmail }}</td>
                        <td>{{ customer.customerNuit }}</td>
                        <td>{{ customer.customerProfession }}</td>
                        <td>{{ customer.customerAddress }}</td>
                        <td v-date-format="customer.createdAt"></td>
                        <td>
                          <b-row>
                            <b-col
                              class="text-center"
                              @click="deleteCustomer(customer.id)"
                              ><b-icon
                                icon="trash-fill"
                                variant="danger"
                              ></b-icon
                            ></b-col>
                            <b-col
                              class="text-center"
                              @click="updateCustomer(customer)"
                              ><b-icon
                                icon="pen-fill"
                                variant="primary"
                              ></b-icon
                            ></b-col>
                            <b-col
                              class="text-center"
                              @click="openCustomerPanel(customer)"
                              ><b-icon
                                icon="eye-fill"
                                variant="success"
                              ></b-icon
                            ></b-col>
                          </b-row>
                        </td>
                      </tr>
                    </tbody>
                  </table>
                </b-overlay>
              </b-col>
            </b-row>
          </b-col>
          <b-col>
            <b-icon
              icon="person-plus-fill"
              variant="dark"
              font-scale="1.5"
            ></b-icon
            >&nbsp;&nbsp;<b style="font-size: 12pt; color: black" class="mb-1"
              >Novo mutuário</b
            >
            <!-- <hr class="bg-secondary mt-0 mb-1" /> -->
            <b-input-group size="sm" class="">
              <b-input-group-prepend is-text>
                <b-icon icon="person-fill"></b-icon>
              </b-input-group-prepend>
              <b-form-input
                type="text"
                size="sm"
                v-model="form.customerName"
                placeholder="Nome do mutuário"
              ></b-form-input>
            </b-input-group>

            <b-input-group size="sm" class="mt-1">
              <b-input-group-prepend is-text>
                <b-icon icon="phone-fill"></b-icon>
              </b-input-group-prepend>
              <b-form-input
                type="number"
                size="sm"
                v-model="form.customerPhone"
                placeholder="Telemóvel"
              ></b-form-input>
            </b-input-group>

            <b-input-group size="sm" class="mt-1">
              <b-input-group-prepend is-text>
                <b-icon icon="envelope-fill"></b-icon>
              </b-input-group-prepend>
              <b-form-input
                type="email"
                size="sm"
                v-model="form.customerEmail"
                placeholder="E-mail"
              ></b-form-input>
            </b-input-group>

            <b-input-group size="sm" class="mt-1">
              <b-input-group-prepend is-text>
                <b-icon icon="pen-fill"></b-icon>
              </b-input-group-prepend>
              <b-form-input
                type="number"
                size="sm"
                v-model="form.customerNuit"
                placeholder="NUIT"
              ></b-form-input>
            </b-input-group>

            <b-input-group size="sm" class="mt-1">
              <b-input-group-prepend is-text>
                <b-icon icon="file-earmark-text-fill"></b-icon>
              </b-input-group-prepend>
              <b-form-input
                type="text"
                size="sm"
                v-model="form.customerNationalId"
                placeholder="Documento de Identidade ou passaporte"
              ></b-form-input>
            </b-input-group>

            <b-input-group size="sm" class="mt-1">
              <b-input-group-prepend is-text>
                <b-icon icon="pin-map-fill"></b-icon>
              </b-input-group-prepend>
              <b-form-input
                type="text"
                size="sm"
                v-model="form.customerAddress"
                placeholder="Local de residência"
              ></b-form-input>
            </b-input-group>

            <b-input-group size="sm" class="mt-1">
              <b-input-group-prepend is-text>
                <b-icon icon="bank"></b-icon>
              </b-input-group-prepend>
              <b-form-input
                type="text"
                size="sm"
                v-model="form.customerLocalOfWork"
                placeholder="Entidade Patronal"
              ></b-form-input>
            </b-input-group>

            <b-input-group size="sm" class="mt-1">
              <b-input-group-prepend is-text>
                <b class="text-secondary" style="font-size: 10pt">MZN</b>
              </b-input-group-prepend>
              <b-form-input
                type="number"
                size="sm"
                step="any"
                v-model="form.customerMonthlySalary"
                placeholder="Rendimento mensal"
              ></b-form-input>
            </b-input-group>

            <b-input-group size="sm" class="mt-1">
              <b-input-group-prepend is-text>
                <b-icon icon="gear-fill"></b-icon>
              </b-input-group-prepend>
              <b-form-input
                type="text"
                size="sm"
                v-model="form.customerProfession"
                placeholder="Profissão ou ocupação"
              ></b-form-input>
            </b-input-group>

            <b-form-group label="Estado civil:" label-for="input-4">
              <b-form-select
                class="mt-0"
                v-model="form.maritalStatus"
                size="sm"
                :options="maritalStatus"
                required
              ></b-form-select>
            </b-form-group>

            <b-input-group
              size="sm"
              class="mt-1"
              v-if="form.maritalStatus != 'casado'"
            >
              <b-input-group-prepend is-text>
                <b-icon icon="person-fill"></b-icon>
              </b-input-group-prepend>
              <b-form-input
                type="text"
                size="sm"
                v-model="form.customerEmergencyPerson"
                placeholder="Pessoa de contacto"
              ></b-form-input>
            </b-input-group>

            <b-input-group
              size="sm"
              class="mt-1"
              v-if="form.maritalStatus != 'casado'"
            >
              <b-input-group-prepend is-text>
                <b-icon icon="phone-fill"></b-icon>
              </b-input-group-prepend>
              <b-form-input
                type="number"
                size="sm"
                v-model="form.customerEmergencyContact"
                placeholder="Contacto de emergência"
              ></b-form-input>
            </b-input-group>

            <b-input-group
              size="sm"
              class="mt-1"
              v-if="form.maritalStatus == 'casado'"
            >
              <b-input-group-prepend is-text>
                <b-icon icon="person-fill"></b-icon>
              </b-input-group-prepend>
              <b-form-input
                type="text"
                size="sm"
                v-model="form.customerSpouseName"
                placeholder="Nome do cônjuje"
              ></b-form-input>
            </b-input-group>

            <b-input-group
              size="sm"
              class="mt-1"
              v-if="form.maritalStatus == 'casado'"
            >
              <b-input-group-prepend is-text>
                <b-icon icon="phone-fill"></b-icon>
              </b-input-group-prepend>
              <b-form-input
                type="text"
                size="sm"
                v-model="form.customerSpouseContact"
                placeholder="Contacto do cônjuge"
              ></b-form-input>
            </b-input-group>

            <b-form-group label="Tipo de financiamento:" label-for="input-5">
              <b-form-select
                v-model="form.interestRateId"
                size="sm"
                :options="typeOfCredit"
                required
              ></b-form-select>
            </b-form-group>
            <b-row>
              <b-col lg="6" md="6" sm="12" class="d-flex align-items-center">
                <b-button
                  :disabled="isLoading"
                  type="button"
                  size="sm"
                  block
                  variant="danger"
                  @click="resetFields()"
                  ><b-icon icon="eraser-fill"></b-icon> &nbsp;Reset</b-button
                >
              </b-col>
              <b-col lg="6" md="6" sm="12" class="d-flex align-items-center">
                <b-button
                  :disabled="isLoading"
                  type="submit"
                  size="sm"
                  block
                  variant="success"
                  v-if="customerUpdationId == 0"
                  @click="registerNewCustomer()"
                  >Cadastrar &nbsp;<b-icon icon="person-plus-fill"></b-icon
                ></b-button>
                <b-button
                  :disabled="isLoading"
                  type="submit"
                  size="sm"
                  block
                  variant="primary"
                  v-else
                  @click="registerNewCustomer()"
                  >Actualizar &nbsp;<b-icon icon="telegram"></b-icon
                ></b-button>
              </b-col>
            </b-row>
          </b-col>
        </b-row>
      </div>
    </div>
    <b-modal hide-footer ref="delete-customer" title="Deletar">
      <p class="text-danger text-center">
        Deseja realmente excluir este mutuário?
      </p>
      <b-row>
        <b-col>
          <b-button block size="sm" @click="cancelDeletion()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button block size="sm" variant="danger" @click="decidedToDelete()"
            >Deletar</b-button
          >
        </b-col>
      </b-row>
    </b-modal>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import moment from "moment";
moment.locale("pt-br");
// import getBase64ImageFromURL from "../utils/getBase64ImageFromURL";
import DateFormat from "../utils/dateFormat";

import NavBarVue from "@/components/NavBar";
import exportFromJSON from "export-from-json";

import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;

export default {
  name: "CustomerComponent",
  data: () => ({
    searchValues: "",
    form: {
      customerName: "",
      customerEmail: "",
      customerPhone: "",
      customerNuit: "",
      customerNationalId: "",
      customerDateOfBirth: "",
      customerMonthlySalary: 0,
      customerAddress: "",
      customerProfession: "",
      customerLocalOfWork: "",
      maritalStatus: "solteiro",
      customerSpouseName: "",
      customerSpouseContact: "",
      customerEmergencyPerson: "",
      customerEmergencyContact: "",
      customerStatus: 0,
      interestRateId: 0,
    },
    maritalStatus: [
      { text: "Solteiro(a)", value: "solteiro" },
      { text: "Casado(a)", value: "casado" },
      { text: "Divorciado(a)", value: "divorciado" },
      { text: "Viúvo(a)", value: "viúvo" },
    ],
    typeOfCredit: [],
    customerUpdationId: 0,
  }),

  components: {
    NavBarVue,
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "company",
      "customers",
      "interestRates",
      "updatedPassword",
    ]),
  },

  created() {
    this.checkPasswordStatus();
    this.interestRates.forEach((rate) => {
      let item = { text: `${rate.tax * 100}% - ${rate.name}`, value: rate.id };
      this.typeOfCredit.push(item);
    });
  },

  methods: {
    checkPasswordStatus() {
      this.user.updatedPassword == 1 ? "" : this.$router.replace("/profile");
    },

    searchCustomers() {},

    openCustomerPanel(customer) {
      this.$store.commit("SET_CURRENT_CUSTOMER", customer);
      this.$router.replace("/customer");
    },

    refreshCustomers() {
      this.$store.dispatch("getAllCustomers", this.company.id);
    },

    deleteCustomer(id) {
      this.customerUpdationId = id;
      this.$refs["delete-customer"].show();
    },

    cancelDeletion() {
      this.userDeletionId = 0;
      this.$refs["delete-customer"].hide();
    },

    decidedToDelete() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/customer/${this.customerUpdationId}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);
            this.$store.dispatch("getAllCustomers");
          } else {
            this.showToast("Erro!", "warning", data.message);
          }
          this.cancelDeletion();
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.cancelDeletion();
          this.$store.commit("LOADING_STATUS", false);
          this.showToast("Erro!", "danger", err.message);
        });
    },

    updateCustomer(customer) {
      this.customerUpdationId = customer.id;
      this.form = customer;
    },

    registerNewCustomer() {
      if (this.form.customerName.length < 6) {
        this.showToast(
          "Avizo!",
          "warning",
          "O campo nome deve conter no mínimo 6 caracteres."
        );
        return;
      }
      if (this.form.customerEmail.length < 10) {
        this.showToast(
          "Avizo!",
          "warning",
          "O campo E-mail deve conter no mínimo 10 caracteres."
        );
        return;
      }
      if (this.form.customerPhone.length != 12) {
        this.showToast(
          "Avizo!",
          "warning",
          "O campo Telemóvel deve conter 12 dígitos."
        );
        return;
      }
      if (this.form.customerNuit.length != 9) {
        this.showToast(
          "Avizo!",
          "warning",
          "O campo NUIT deve conter 9 dígitos."
        );
        return;
      }
      if (this.form.customerNationalId.length < "4") {
        this.showToast(
          "Avizo!",
          "warning",
          "O campo Bilhete de Identidade deve conter 4 caracteres."
        );
        return;
      }
      if (this.form.customerAddress.length < 4) {
        this.showToast(
          "Avizo!",
          "warning",
          "O endereço do cliente deve ser preenchido."
        );
        return;
      }
      if (this.form.customerLocalOfWork.length < 4) {
        this.showToast(
          "Avizo!",
          "warning",
          "A entidade patronal do cliente deve ser preenchido."
        );
        return;
      }
      if (parseFloat(this.form.customerMonthlySalary) < 5200) {
        this.showToast(
          "Avizo!",
          "warning",
          "O rendimento mensal do mutuário deve ser no mínimo de 5,200.00 MZN"
        );
        return;
      }
      if (this.form.customerProfession.length < 4) {
        this.showToast(
          "Avizo!",
          "warning",
          "A profissão do mutuário deve ser preenchido."
        );
        return;
      }
      if (this.form.interestRateId <= 0) {
        this.showToast(
          "Avizo!",
          "warning",
          "Seleccione o tipo de financiamento por favor."
        );
        return;
      }

      if (this.customerUpdationId == 0) {
        this.form.companyId = this.company.id;
        axios
          .post("/api/customer", this.form)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              this.$store.dispatch("getAllCustomers", this.company.id);
              this.showToast("Sucesso!", "success", data.message);
            } else {
              this.showToast("Avizo!", "danger", data.message);
            }
            this.$store.commit("LOADING_STATUS", false);
            this.resetFields();
          })
          .catch((err) => {
            console.log(err);
            this.showToast("Avizo!", "danger", err.message);
            this.$store.commit("LOADING_STATUS", false);
          });
      } else {
        axios
          .put(`/api/customer/${this.customerUpdationId}`, this.form)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              this.$store.dispatch("getAllCustomers", this.company.id);
              this.showToast("Sucesso!", "success", data.message);
            } else {
              this.showToast("Avizo!", "danger", data.message);
            }
            this.$store.commit("LOADING_STATUS", false);
            this.resetFields();
          })
          .catch((err) => {
            console.log(err);
            this.showToast("Avizo!", "danger", err.message);
            this.$store.commit("LOADING_STATUS", false);
          });
      }
    },

    async downloadCustomerList() {
      const body = [];

      for (let row of this.customers) {
        const rows = [];

        // rows.push({ text: row.id, fontSize: 8 })
        rows.push({ text: row.customerName, fontSize: 7 });
        rows.push({ text: row.customerEmail, fontSize: 7 });
        rows.push({ text: row.customerPhone, fontSize: 7 });
        rows.push({ text: row.customerNuit, fontSize: 7 });
        rows.push({ text: row.customerProfession, fontSize: 7 });
        rows.push({ text: DateFormat.formatDate(row.createdAt), fontSize: 7 });

        body.push(rows);
      }

      let docDefinition = {
        // watermark: { text: this.company[0].name, opacity: 0.08 },
        header: [
          // {
          //   image: await getBase64ImageFromURL(this.company.companyLogo),
          //   width: 300,
          //   height: 200,
          //   margin: [30, 0, 0, 0],
          // },
        ],
        footer: {
          columns: [
            {
              text: "Documento processado por computador",
              alignment: "left",
              fontSize: 8,
              margin: [30, 0, 0, 0],
            },
            {
              text: "Microcrédito Software",
              alignment: "right",
              fontSize: 8,
              margin: [0, 0, 30, 0],
            },
          ],
        },

        content: [
          {
            columns: [
              [
                {
                  text: `\nData de impressão: ${DateFormat.formatDate(
                    new Date()
                  )}`,
                  fontSize: 8,
                  alignment: "left",
                },
              ],
            ],
          },
          {
            text: "\n",
          },
          {
            text: `Total de mutuários cadastrados: ${this.customers.length}`,
            bold: true,
            fontSize: 12,
            alignment: "left",
          },
          {
            text: "\n",
          },
          {
            table: {
              widths: ["*", "auto", "auto", "auto", "auto", "auto"],
              body: [
                [
                  { text: "Nome do mutuário", style: "columnsTitle" },
                  { text: "E-mail", style: "columnsTitle" },
                  { text: "Telefone", style: "columnsTitle" },
                  { text: "NUIT", style: "columnsTitle" },
                  { text: "Profissão", style: "columnsTitle" },
                  { text: "Data", style: "columnsTitle" },
                ],
                ...body,
                [{ text: "\n\n" }, {}, {}, {}, {}, {}],
              ],
            },
            layout: "lightHorizontalLines",
          },
        ],
        styles: {
          paymentMethodStyle: {
            bold: true,
            fontSize: 10,
          },
          sectionHeader: {
            bold: true,
            fontSize: 8,
            margin: [0, 15, 0, 15],
          },
          columnsTitle: {
            fontSize: 8,
            bold: true,
            color: "#000000",
          },
          columnsSubTotals: {
            fontSize: 10,
            bold: true,
            color: "#000000",
          },
          columnsTotal: {
            fontSize: 12,
            bold: true,
            color: "#000000",
          },
          companyDetailsStyle: {
            fontSize: 9,
            bold: true,
            color: "#000000",
          },
          customerStyle: {
            fontSize: 10,
            bold: false,
          },
        },
      };

      // pdfMake.createPdf(docDefinition).download(`proforma${this.currentQuotation.name}.pdf`);
      pdfMake.createPdf(docDefinition).open();
    },

    downloadCustomerListExcel() {
      const body = [];

      for (let customer of this.customers) {
        const row = {
          "Nº Conta": customer.accountNumber,
          Nome: customer.customerName,
          Email: customer.customerEmail,
          Telemóvel: customer.customerPhone,
          NUIT: customer.customerNuit,
          "Bilhte de identidade": customer.customerNationalId,
          Profissão: customer.customerProfession,
          "Entidade patronal": customer.customerLocalOfWork,
          Salário: customer.customerMonthlySalary,
          "Estado civil": customer.maritalStatus,
          Endereço: customer.customerAddress,
          Status: customer.customerStatus,
          "Data de cadastro": DateFormat.formatDate(customer.createdAt),
        };
        body.push(row);
      }
      const fileName = "Lista_de_clientes";
      const data = body;
      const exportType = "xls";

      exportFromJSON({ data, fileName, exportType });
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    resetFields() {
      this.customerUpdationId = 0;
      this.form = {
        customerName: "",
        customerEmail: "",
        customerPhone: "",
        customerNuit: "",
        customerNationalId: "",
        customerDateOfBirth: "",
        customerMonthlySalary: 0,
        customerAddress: "",
        customerProfession: "",
        customerLocalOfWork: "",
        maritalStatus: "solteiro",
        customerSpouseName: "",
        customerSpouseContact: "",
        customerEmergencyPerson: "",
        customerEmergencyContact: "",
        customerStatus: 0,
        interestRateId: 1,
      };
    },
  },
};
</script>
<style lang="scss" scoped>
.container-group {
  overflow: hidden auto;
  margin-left: -15px;
  width: calc(100% + 30px);
  height: calc(100vh - 69px);

  .container {
